double convertAdcCodeToVoltage(unsigned int adcCode, unsigned int resolutionBits, double referenceVoltage) {
    if (resolutionBits == 0 || resolutionBits > 31) throw invalid_argument("resolutionBits deve estar entre 1 e 31");
    unsigned int maximumCode = (1u << resolutionBits) - 1u;
    if (adcCode > maximumCode) throw out_of_range("adcCode excede a resolução");
    return referenceVoltage * static_cast<double>(adcCode) / maximumCode;
}
